namespace nfs_hd { namespace {
constexpr size_t MaxOriginal=8u*1024u*1024u;
void need(bool b,const char*m){if(!b)throw std::runtime_error(m);}
uint32_t le32(const uint8_t*p){return uint32_t(p[0])|(uint32_t(p[1])<<8)|(uint32_t(p[2])<<16)|(uint32_t(p[3])<<24);}
uint64_t le64(const uint8_t*p){return uint64_t(le32(p))|(uint64_t(le32(p+4))<<32);}
bool hash(const uint8_t*p,size_t n,const Digest&expected){Digest d{};return nfs_texture_sha256(p,n,d.data())&&d==expected;}
std::vector<uint8_t>read(const std::string&path,size_t limit){std::ifstream f(path,std::ios::binary);need(bool(f),"Owned artwork input unavailable");f.seekg(0,std::ios::end);auto n=f.tellg();need(n>0&&uint64_t(n)<=limit,"Owned artwork input bounds");f.seekg(0);std::vector<uint8_t>b(size_t(n),0);f.read(reinterpret_cast<char*>(b.data()),std::streamsize(b.size()));need(f.gcount()==std::streamsize(b.size())&&f.peek()==std::char_traits<char>::eof(),"Owned artwork input changed");return b;}
std::vector<uint8_t>decode(const std::vector<uint8_t>&src){need(src.size()>=5&&src.size()<=MaxOriginal&&src[0]==0x10&&src[1]==0xfb,"Owner QFS header");size_t length=(size_t(src[2])<<16)|(size_t(src[3])<<8)|src[4];need(length>=16&&length<=MaxOriginal,"Owner QFS size");std::vector<uint8_t>out;out.reserve(length);size_t at=5;bool terminal=false;auto next=[&](){need(at<src.size(),"Owner QFS truncated");return unsigned(src[at++]);};
 while(at<src.size()){unsigned command=next(),literal=0,count=0,back=0;if(command<0x80){unsigned b=next();literal=command&3;count=((command&28)>>2)+3;back=((command&96)<<3)+b+1;}else if(command<0xc0){unsigned b=next(),c=next();literal=b>>6;count=(command&63)+4;back=((b&63)<<8)+c+1;}else if(command<0xe0){unsigned b=next(),c=next(),e=next();literal=command&3;count=((command&12)<<6)+e+5;back=((command&16)<<12)+(b<<8)+c+1;}else if(command<0xfc)literal=((command&31)<<2)+4;else{literal=command&3;terminal=true;}
  need(literal<=src.size()-at&&out.size()<=length&&size_t(literal)+count<=length-out.size(),"Owner QFS copy bounds");out.insert(out.end(),src.begin()+at,src.begin()+at+literal);at+=literal;if(count){need(back>=1&&back<=out.size(),"Owner QFS back reference");while(count--)out.push_back(out[out.size()-back]);}if(terminal)break;
 }need(terminal&&at==src.size()&&out.size()==length,"Owner QFS terminal");return out;}
std::string ownerFile(const std::string&root){namespace fs=std::filesystem;auto current=fs::canonical(fs::path(root));need(fs::is_directory(current),"Owner root directory");const char*parts[]={"fedata","pc","art","main.qfs"};for(const char*part:parts){fs::path match;unsigned count=0,scanned=0;for(const auto&entry:fs::directory_iterator(current)){need(++scanned<=4096,"Owner directory bounds");auto name=entry.path().filename().string();for(char&c:name)if(c>='A'&&c<='Z')c=char(c-'A'+'a');if(name==part){match=entry.path();need(++count==1,"Ambiguous owner component");}}need(count==1&&!fs::is_symlink(fs::symlink_status(match)),"Missing/symlink owner component");current=match;}need(fs::is_regular_file(current),"Owner archive file");return current.string();}
using Entry=std::pair<size_t,size_t>;
std::map<std::string,Entry>directory(const std::vector<uint8_t>&d){need(d.size()>=16&&!std::memcmp(d.data(),"SHPI",4)&&le32(d.data()+4)==d.size(),"Owner FSH header");size_t count=le32(d.data()+8);need(count&&count<=4096&&16+count*8<=d.size(),"Owner FSH directory bounds");std::map<size_t,std::string>ordered;std::set<std::string>names;for(size_t i=0;i<count;++i){const auto*p=d.data()+16+i*8;std::string name(reinterpret_cast<const char*>(p),4);size_t offset=le32(p+4);need(offset>=16+count*8&&offset<=d.size()-16&&names.insert(name).second&&ordered.emplace(offset,name).second,"Owner FSH duplicate/offset");}std::map<std::string,Entry>result;for(auto i=ordered.begin();i!=ordered.end();++i){auto j=i;++j;size_t end=j==ordered.end()?d.size():j->first;need(end-i->first>=16,"Owner FSH overlap");result.emplace(i->second,Entry{i->first,end-i->first});}return result;}
struct Inflater{z_stream z{};bool initialized=false,ended=false;explicit Inflater(const uint8_t*p,size_t n){need(n<=std::numeric_limits<uInt>::max(),"Template compressed bounds");z.next_in=const_cast<Bytef*>(p);z.avail_in=uInt(n);need(inflateInit(&z)==Z_OK,"Template inflater init");initialized=true;}~Inflater(){if(initialized)inflateEnd(&z);}void segment(uint8_t*out,size_t n){need(n<=std::numeric_limits<uInt>::max(),"Template segment bounds");if(!n)return;need(!ended,"Template premature terminal");z.next_out=out;z.avail_out=uInt(n);while(z.avail_out){uLong beforeIn=z.total_in,beforeOut=z.total_out;int r=inflate(&z,Z_NO_FLUSH);need(r==Z_OK||r==Z_STREAM_END,"Template inflate failure");need(z.total_in!=beforeIn||z.total_out!=beforeOut,"Template inflate stalled");if(r==Z_STREAM_END){ended=true;need(z.avail_out==0,"Template short output");break;}}}void finish(){uint8_t extra=0;if(!ended){z.next_out=&extra;z.avail_out=1;uLong before=z.total_out;int r=inflate(&z,Z_FINISH);need(r==Z_STREAM_END&&z.total_out==before,"Template trailing output");ended=true;}need(z.avail_in==0&&z.total_out==owned_recipe::PayloadBytes,"Template trailing input/length");}};
}
std::shared_ptr<const ArtworkPack>loadBundledOwnedArtwork(const std::string&root,const std::string&path,const Digest&expected,std::string*error)noexcept{try{
 need(expected==owned_recipe::OutputSha,"Configured artwork release mismatch");auto compressed=read(path,owned_recipe::TemplateBytes);need(compressed.size()==owned_recipe::TemplateBytes&&hash(compressed.data(),compressed.size(),owned_recipe::TemplateSha),"Bundled template identity");need(compressed.size()>16&&!std::memcmp(compressed.data(),"OWNZ0001",8)&&le64(compressed.data()+8)==owned_recipe::PayloadBytes,"Bundled template format");
 auto owner=read(ownerFile(root),MaxOriginal);need(hash(owner.data(),owner.size(),owned_recipe::OwnerSha),"Owner archive identity");auto decoded=decode(owner);need(hash(decoded.data(),decoded.size(),owned_recipe::DecodedSha),"Decoded owner identity");auto entries=directory(decoded);
 std::vector<uint8_t>output(owned_recipe::OutputBytes,0);Inflater stream(compressed.data()+16,compressed.size()-16);size_t cursor=0;for(const auto&h:owned_recipe::holes){need(h.output>=cursor&&h.output<=output.size()-16&&h.source<=decoded.size()&&h.span<=decoded.size()-h.source&&h.span>=16,"Owner hole bounds");auto e=entries.find(std::string(h.name,4));need(e!=entries.end()&&e->second==Entry{h.source,h.span}&&hash(decoded.data()+h.source,h.span,h.sha),"Owner entry identity");stream.segment(output.data()+cursor,h.output-cursor);std::memcpy(output.data()+h.output,decoded.data()+h.source,16);cursor=h.output+16;}stream.segment(output.data()+cursor,output.size()-cursor);stream.finish();need(hash(output.data(),output.size(),owned_recipe::OutputSha),"Reconstructed artwork identity");return ArtworkPack::loadOwned(std::move(output),expected,error);
 }catch(const std::exception&e){try{if(error)*error=e.what();}catch(...){}return {};}catch(...){try{if(error)*error="Owned artwork reconstruction failed";}catch(...){}return {};}}
}
